import{_ as o,r as e,o as r,c,e as t,a as i,s as l}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Controllers & AJAX - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":3,"title":"Class definition","slug":"class-definition","link":"#class-definition","children":[]},{"level":3,"title":"Controller properties","slug":"controller-properties","link":"#controller-properties","children":[]},{"level":2,"title":"Actions, views and routing","slug":"actions-views-and-routing","link":"#actions-views-and-routing","children":[]},{"level":2,"title":"Passing data to views","slug":"passing-data-to-views","link":"#passing-data-to-views","children":[]},{"level":2,"title":"Setting the navigation context","slug":"setting-the-navigation-context","link":"#setting-the-navigation-context","children":[]},{"level":2,"title":"Using AJAX handlers","slug":"using-ajax-handlers","link":"#using-ajax-handlers","children":[{"level":3,"title":"Back-end AJAX handlers","slug":"back-end-ajax-handlers","link":"#back-end-ajax-handlers","children":[]},{"level":3,"title":"Triggering AJAX requests","slug":"triggering-ajax-requests","link":"#triggering-ajax-requests","children":[]}]},{"level":2,"title":"Controller middleware","slug":"controller-middleware","link":"#controller-middleware","children":[]}],"relativePath":"1.x/backend/controllers-ajax.md","filePath":"1.x/backend/controllers-ajax.md"}'),p={name:"1.x/backend/controllers-ajax.md"};function d(u,n,h,g,k,m){const a=e("pre-heading"),s=e("post-heading");return r(),c("div",null,[t(a),n[0]||(n[0]=i("h1",null,"Controllers & AJAX",-1)),t(s),n[1]||(n[1]=l(`<p>October back-end implements the MVC pattern. Controllers manage back-end pages and implement various features like forms and lists. This article describes how to develop back-end controllers and how to configure controller behaviors.</p><p>Each controller is represented with a PHP script which resides in the the <strong>/controllers</strong> subdirectory of a Plugin directory. Controller views are <code>.htm</code> files that reside in the controller view directory. The controller view directory name matches the controller class name written in lowercase. The view directory can also contain controller configuration files. An example of a controller directory structure:</p><pre><code>plugins/
  acme/
    blog/
      controllers/
        users/                &lt;=== Controller view directory
          _partial.htm        &lt;=== Controller partial file
          config_form.yaml    &lt;=== Controller config file
          index.htm           &lt;=== Controller view file
        Users.php             &lt;=== Controller class
      Plugin.php
</code></pre><h3 id="class-definition"><a href="#class-definition" class="header-anchor">#</a> Class definition</h3><p>Controller classes must extend the <code>\\Backend\\Classes\\Controller</code> class. As any other plugin class, controllers should belong to the <a href="./../plugin/registration.html#plugin-namespaces">plugin namespace</a>. The most basic representation of a Controller used inside a Plugin looks like this:</p><pre><code>namespace Acme\\Blog\\Controllers;

class Posts extends \\Backend\\Classes\\Controller {

    public function index()    // &lt;=== Action method
    {

    }
}
</code></pre><p>Usually each controller implements functionality for working with a single type of data - like blog posts or categories. All back-end behaviors described below assume this convention.</p><h3 id="controller-properties"><a href="#controller-properties" class="header-anchor">#</a> Controller properties</h3><p>The back-end controller base class defines a number of properties that allow to configure the page appearance and manage the page security:</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>$fatalError</strong></td><td>allows to store a fatal exception generated in an action method in order to display it in the view.</td></tr><tr><td><strong>$user</strong></td><td>contains a reference to the the back-end user object.</td></tr><tr><td><strong>$suppressView</strong></td><td>allows to prevent the view display. Can be updated in the action method or in the controller constructor.</td></tr><tr><td><strong>$params</strong></td><td>an array of the routed parameters.</td></tr><tr><td><strong>$action</strong></td><td>a name of the action method being executed in the current request.</td></tr><tr><td><strong>$publicActions</strong></td><td>defines an array of actions available without the back-end user authentication. Can be overridden in the class definition.</td></tr><tr><td><strong>$requiredPermissions</strong></td><td>permissions required to view this page. Can be set in the class definition or in the controller constructor. See <a href="./users.html">users &amp; permissions</a> for details.</td></tr><tr><td><strong>$pageTitle</strong></td><td>sets the page title. Can be set in the action method.</td></tr><tr><td><strong>$bodyClass</strong></td><td>body class property used for customizing the layout. Can be set in the controller constructor or action method.</td></tr><tr><td><strong>$guarded</strong></td><td>controller specific methods which cannot be called as actions. Can be extended in the controller constructor.</td></tr><tr><td><strong>$layout</strong></td><td>specify a custom layout for the controller views (see <a href="./../backend/views-partials.html#layouts-and-child-layouts">layouts</a>).</td></tr></tbody></table></div><h2 id="actions-views-and-routing"><a href="#actions-views-and-routing" class="header-anchor">#</a> Actions, views and routing</h2><p>Public controller methods, called <strong>actions</strong> are coupled to <strong>view files</strong> which represent the page corresponding the action. Back-end view files use PHP syntax. Example of the <strong>index.htm</strong> view file contents, corresponding to the <strong>index</strong> action method:</p><pre><code>&lt;h1&gt;Hello World&lt;/h1&gt;
</code></pre><p>URL of this page is made up of the author name, plugin name, controller name and action name.</p><pre><code>backend/[author name]/[plugin name]/[controller name]/[action name]
</code></pre><p>The above Controller results in the following:</p><pre><code>http://example.com/backend/acme/blog/users/index
</code></pre><h2 id="passing-data-to-views"><a href="#passing-data-to-views" class="header-anchor">#</a> Passing data to views</h2><p>Use the controller&#39;s <code>$vars</code> property to pass any data directly to your view:</p><pre><code>$this-&gt;vars[&#39;myVariable&#39;] = &#39;value&#39;;
</code></pre><p>The variables passed with the <code>$vars</code> property can now be accessed directly in your view:</p><pre><code>&lt;p&gt;The variable value is &lt;?= $myVariable ?&gt;&lt;/p&gt;
</code></pre><h2 id="setting-the-navigation-context"><a href="#setting-the-navigation-context" class="header-anchor">#</a> Setting the navigation context</h2><p>Plugins can register the back-end navigation menus and submenus in the <a href="./../plugin/registration.html#navigation-menus">plugin registration file</a>. The navigation context determines what back-end menu and submenu are active for the current back-end page. You can set the navigation context with the <code>BackendMenu</code> class:</p><pre><code>BackendMenu::setContext(&#39;Acme.Blog&#39;, &#39;blog&#39;, &#39;categories&#39;);
</code></pre><p>The first parameter specifies the author and plugin names. The second parameter sets the menu code. The optional third parameter specifies the submenu code. Usually you call the <code>BackendMenu::setContext</code> in the controller constructor.</p><pre><code>namespace Acme\\Blog\\Controllers;

class Categories extends \\Backend\\Classes\\Controller {

public function __construct()
{
    parent::__construct();

    BackendMenu::setContext(&#39;Acme.Blog&#39;, &#39;blog&#39;, &#39;categories&#39;);
}
</code></pre><p>You can set the title of the back-end page with the <code>$pageTitle</code> property of the controller class (note that the form and list behaviors can do it for you):</p><pre><code>$this-&gt;pageTitle = &#39;Blog categories&#39;;
</code></pre><h2 id="using-ajax-handlers"><a href="#using-ajax-handlers" class="header-anchor">#</a> Using AJAX handlers</h2><p>The back-end AJAX framework uses the same <a href="./../ajax/introduction.html">AJAX library</a> as the front-end pages. The library is loaded automatically on the back-end pages.</p><h3 id="back-end-ajax-handlers"><a href="#back-end-ajax-handlers" class="header-anchor">#</a> Back-end AJAX handlers</h3><p>The back-end AJAX handlers can be defined in the controller class or <a href="./widgets.html">widgets</a>. In the controller class the AJAX handlers are defined as public methods with the name starting with &quot;on&quot; string: <strong>onCreateTemplate</strong>, <strong>onGetTemplateList</strong>, etc.</p><p>Back-end AJAX handlers can return an array of data, throw an exception or redirect to another page (see <a href="./../ajax/handlers.html">AJAX event handlers</a>). You can use <code>$this-&gt;vars</code> to set variables and the controller&#39;s <code>makePartial</code> method to render a partial and return its contents as a part of the response data.</p><pre><code>public function onOpenTemplate()
{
    if (Request::input(&#39;someVar&#39;) != &#39;someValue&#39;) {
        throw new ApplicationException(&#39;Invalid value&#39;);
    }

    $this-&gt;vars[&#39;foo&#39;] = &#39;bar&#39;;

    return [
        &#39;partialContents&#39; =&gt; $this-&gt;makePartial(&#39;some-partial&#39;)
    ];
}
</code></pre><h3 id="triggering-ajax-requests"><a href="#triggering-ajax-requests" class="header-anchor">#</a> Triggering AJAX requests</h3><p>The AJAX request can be triggered with the data attributes API or the JavaScript API. Please see the <a href="./../ajax/introduction.html">front-end AJAX library</a> for details. The following example shows how to trigger a request with a back-end button.</p><pre><code>&lt;button
    type=&quot;button&quot;
    data-request=&quot;onDoSomething&quot;
    class=&quot;btn btn-default&quot;&gt;
    Do something
&lt;/button&gt;
</code></pre><blockquote><p><strong>Note</strong>: You can specifically target the AJAX handler of a widget using a prefix <code>widget::onName</code>. See the <a href="./../backend/widgets.html#ajax-handlers">widget AJAX handler article</a> for more details.</p></blockquote><h2 id="controller-middleware"><a href="#controller-middleware" class="header-anchor">#</a> Controller middleware</h2><p>You can define middleware in your Backend controllers, providing you with a convenient mechanism for making changes to the response of a HTTP request. For example, you may wish to specify a HTTP header for certain actions in your controller, or redirect users if they don&#39;t meet certain criteria.</p><p>Controller middleware is executed after the request is processed by October CMS, but before the response is sent to the browser.</p><p>To define middleware for your controller, you may specify it in the <code>__construct()</code> method of your Backend controller by calling the <code>middleware()</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">middleware</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">,</span> <span class="token variable">$response</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Middleware functionality</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>middleware()</code> method requires a callback with two arguments, <code>$request</code> providing the <a href="./../services/request-input.html#request-information">request information</a> and <code>$response</code> providing the <a href="./../services/response-view.html#basic-responses">response object</a>. The callback should return the <code>$response</code> object with your modifications.</p><p>As an example, to add a <code>Test-Header</code> header to your response, you could do the following:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">middleware</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">,</span> <span class="token variable">$response</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$response</span><span class="token operator">-&gt;</span><span class="token property">headers</span><span class="token operator">-&gt;</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Test-Header&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Test&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> <span class="token variable">$response</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can also control which actions will use your middleware by using the <code>only()</code> and <code>except()</code> modifiers. For example, to restrict the middleware to only run on the <code>index</code> action, you could do the following:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">middleware</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">,</span> <span class="token variable">$response</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Middleware functionality</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">only</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;index&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Alternatively, to run the middleware on every action except the <code>index</code> action:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">middleware</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">,</span> <span class="token variable">$response</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Middleware functionality</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">except</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;index&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,51))])}const w=o(p,[["render",d]]);export{b as __pageData,w as default};
